Method.Implementation:
 #dim status as %Status	 
 set status = $$$OK

 $$$TRACE("Inside OnMessage method<" _ pRequest.StringValue _ ">")
 $$$TRACE("App Address:" _ ..ApplicationAddress)
 $$$TRACE("Tuxedo service: " _ ..TuxedoService)	 
 $$$TRACE("Jar file: " _ ..JarFile)

 do ..JavaGateway.%Import(..JarFile) 	 
 //Set tSC = ..GetConnection(.tJavaGateway)
 try{
	 set ..objCdrTuxService = ##class(org.ihc.itf.cdr.voser.HasAdmitPrivilegeFromCode).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)		
 	 set pResponse = ##class(Ens.StringResponse).%New()
 	 set pResponse.StringValue=""
 	 set args = pRequest.StringValue
 	 $$$TRACE("Call method getAdmitPrivilege("_$P(args,";",1)_","_$P(args,";",3)_","_$P(args,";",2)_","_$P(args,";",4)_")")
 	 try {		 
		set output = ..objCdrTuxService.getAdmitPrivilege($P(args,";",1),$P(args,";",3),$P(args,";",2),$P(args,";",4))
		$$$TRACE("Output after invocation of getAdmitPrivilege Java Method:"_output)

		if (output'=""){
			set pResponse.StringValue = output
		}

 	 } catch err {		 	
    	$$$TRACE("Exception in calling getAdmitPrivilege; AsSystemError is: " _err.AsSystemError() _ ";$ZERROR: " _ $ZERROR _ ";ErrName: " _ $ZCVT(err.Name,"O","HTML")_ "; ErrData: " _ err.Data _ "; ErrCode:" _ err.Code _ "ErrLocation:" _ err.Location)	    

    	set status = $$$ERROR("Exception in calling getAdmitPrivilege " _ err.Data)		    	     	 
		set errText = $SYSTEM.Status.GetOneErrorText(status)

		$$$TRACE("errText .." _errText)
    	if errText["CONNECTIONERROR"{		   
	   		set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
    	}	    
    	if errText["RESEND"{
	   		set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError($CLASSNAME(),errText)
    	}
    	if errText["DATAERROR"{
	   		set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
    	}
    	if errText["SHUTDOWN"{
	   		set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
    	}
 	 }

 }catch err{
	 $$$TRACE("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
     set status=$$$ERROR(" Exception while Creating Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)	    
 }


 try {		
	if $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		do ..objCdrTuxService.shutdownTuxService()			
 		set ..objCdrTuxService = $$$NULLOREF
 	}
 } catch {
 	set status = $$$EnsSystemError
 }
 return status
